 border: 1px solid rgba(255,255,255,0.35);
 backdrop-filter: blur(10px);
 transition: all 0.35s ease;
}

.con-btn:hover {
 transform: translateY(-4px);
 background: rgba(255,255,255,0.30);
 box-shadow: 0 0 32px rgba(255,255,255,0.45);
}

/* =================================================
 SECTIONS
 ================================================= */
.con-section {
 margin-bottom: 9px;
}

.con-section h2 {
 font-size: 32px;
 margin-bottom: 18px;
 color: #ffffff !important;
}

.con-section p {
 max-width: 950px;
 color: rgba(255,255,255,0.9);
}

/* =================================================
 GRID & CARDS
 ================================================= */
.con-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
 gap: 32px;
 margin-top: 40px;
}

.con-card {
 background: rgba(255,255,255,0.14);
 border: 1px solid rgba(255,255,255,0.30);
 border-radius: 16px;
 padding: 30px;
 backdrop-filter: blur(12px);
 transition: all 0.45s ease;
}

.con-card:hover {
 transform: translateY(-10px) scale(1.02);
 background: rgba(255,255,255,0.22);
 box-shadow: 0 0 42px rgba(255,255,255,0.38);
}

.con-card h3 {
 font-size: 18px;
 margin-top: 0;
 color: #ffffff !important;
}

/* =================================================
 LIST
 ================================================= */
.con-list {
 padding-left: 18px;
}

.con-list li {
 margin-bottom: 10px;
 color: rgba(255,255,255,0.9);
}

/* =================================================
 CTA
 ================================================= */
.con-cta {
 text-align: center;
 padding: 70px 30px;
 background: rgba(255,255,255,0.12);
 border: 1px solid rgba(255,255,255,0.30);
 border-radius: 22px;
 backdrop-filter: blur(14px);
}

.con-cta h2 {
 color: #ffffff !important;
}

/* =================================================
 SCROLL ANIMATION
 ================================================= */
.con-animate {
 opacity: 0;
 transform: translateY(32px);
 transition: all 0.9s ease;
}

.con-visible {
 opacity: 1;
 transform: translateY(0);
}

.con-delay-1 { transition-delay: 0.1s; }
.con-delay-2 { transition-delay: 0.2s; }
.con-delay-3 { transition-delay: 0.3s; }
</style>
</head>

 

 
 
 
 Consultancy Services</h1>
 
 Strategic, technical, and regulatory consultancy for chemical,
 pharmaceutical, industrial, and infrastructure projects.
 </p>
 Contact Us</a>
 </div>
</section>

 
 
 Professional Industrial Consultancy</h2>
 
 Nayara Industries offers end-to-end consultancy services supporting
 project planning, process optimization, regulatory compliance,
 cost reduction, and operational excellence. Our advisory approach
 combines technical expertise with practical industry experience.
 </p>
</section>

 
 
 Our Consultancy Expertise</h2>

 
 
 Project Feasibility & DPR</h3>
 Techno-economic feasibility studies, DPR preparation, and investment analysis.</p>
 </div>

 
 Process & Technology Advisory</h3>
 Process selection, optimization, scale-up, and technology transfer support.</p>
 </div>

 
 Regulatory & Statutory Consultancy</h3>
 Guidance for pollution control, factory licensing, safety, and compliance.</p>
 </div>

 
 Plant Layout & Engineering Review</h3>
 Review of layouts, utilities, material flow, and safety compliance.</p>
 </div>

 
 Operational Excellence</h3>
 Debottlenecking, yield improvement, cost optimization, and productivity enhancement.</p>
 </div>

 
 Risk & Safety Consulting</h3>
 HAZOP, SOP development, safety audits, and risk mitigation planning.</p>
 </div>
 </div>
</section>

 
 
 Our Consulting Approach</h2>
 
 Client-specific assessment and requirement analysis</li>
 Data-driven recommendations and technical validation</li>
 Practical, implementable solutions</li>
 Compliance-focused execution support</li>
 Long-term value creation</li>
 </ul>
</section>

 
 
 
 Need Expert Industrial Consultancy?</h2>
 
 Partner with Nayara Industries for reliable, practical,
 and results-driven consultancy services.
 </p>
 Contact Us</a>
 </div>
</section>

 
 
(function () {
 const items = document.querySelectorAll('.con-animate');

 const observer = new IntersectionObserver(entries => {
 entries.forEach(entry => {
 if (entry.isIntersecting) {
 entry.target.classList.add('con-visible');
 observer.unobserve(entry.target);
 }
 });
 }, { threshold: 0.15 });

 items.forEach(el => observer.observe(el));
})();
</script>

</body>
</html>
